#!/usr/bin/env python3
"""
Round 159b (culprits), 4 October 2026. Needs round 158b.

Combine the ticked layers made quick.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 159b (4 October)\n\nNeeds round 158b. Carries round 147b, which failed: main had moved on by the time it was uploaded (its test block clashed). No tiles patch. No app.js?v= bump.\n\n- Combine the ticked layers made quick (asked 3 October: "takes way too\n  long"). The cause: points were cut with MapLibre\'s "within" filter against\n  one shape made of every crossing square. Measured: about 2 ms a point with\n  4,000 squares, for each of a point row\'s four layers (dot, haze, core, soft\n  glow), redone for every map square and every change. In Chromium with 5,000\n  points and 300 areas the map took about 61 s to settle (20,000 points: not\n  done after 5 minutes); now about 3 s (20,000 points: about 4 s).\n- Now every layer of a row taking part, points included, is drawn as a copy\n  ("<layer>__cut", its glow "<layer>__cut-haze" etc.) on one source per row\n  and source/source-layer ("<row>__<hash>__cut"), from the row\'s features in\n  the crossings: a point by the square it lies in (comboKeepPoints, one\n  look-up), lines and areas clipped as before but through a 5-degree index of\n  the crossings (comboRectIndex), an area wholly inside one crossing kept\n  whole. The original gets a filter that lets nothing through (COMBO_HIDE); a\n  filter set on it later is kept (COMBO_OWN) and passed to the copy, and its\n  visibility and paint changes follow. Clicks and hovers reach the copies\n  (queryRenderedFeatures asked of a layer also asks its copy; checked in\n  Chromium). Copies are added through the raw addLayer (hudRaw.addLayer), so\n  colours are not mapped twice; the theme\'s own colours are carried over.\n- Also: a GeoJSON row\'s features are read from the source as the map holds\n  them (s._data.geojson), not asked of the worker every run; each row\'s grid\n  is kept and reused while its features, figure and picture are unchanged\n  (COMBO.calc); the run pauses between layers so the page stays usable; the\n  top-fifth sort is a native number sort; tiled features are keyed briefly\n  (comboFeatKey) instead of writing out their geometry; pictures are asked\n  again only when the crossings change (combocut:// carries their number,\n  COMBO.cutHash). The squares past 85 degrees were added back after being\n  cleared; now cleared after.\n- Not seen against the real layers in a browser (the sandbox cannot reach the\n  data); tested with made-up rows. Check live with several rows ticked.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round159b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 158b" not in h.read_text(encoding="utf-8"):
        sys.exit("round159b: round 158b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round159b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round159b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round159b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ""

if __name__ == "__main__":
    main()
